function Get-EmbeddedArchiveBytes {
    param([ValidateSet('Win10', 'Win11')][string]$OperatingSystem = 'Win11')

    $base64 = if ($OperatingSystem -eq 'Win10') { $EmbeddedWin10ArchiveBase64 } else { $EmbeddedArchiveBase64 }
    return [Convert]::FromBase64String(($base64 -replace '\s', ''))
}

function Get-ByteArraySha256 {
    param([Parameter(Mandatory = $true)][byte[]]$Bytes)

    $sha256 = [Security.Cryptography.SHA256]::Create()
    try {
        return ([BitConverter]::ToString($sha256.ComputeHash($Bytes))).Replace('-', '')
    }
    finally {
        $sha256.Dispose()
    }
}

if ($SelfTest) {
    try {
        foreach ($operatingSystem in @('Win10', 'Win11')) {
            $payloadBytes = Get-EmbeddedArchiveBytes -OperatingSystem $operatingSystem
            $payloadHash = Get-ByteArraySha256 -Bytes $payloadBytes
            $expectedHash = if ($operatingSystem -eq 'Win10') { $EmbeddedWin10ArchiveSha256 } else { $EmbeddedArchiveSha256 }
            if ($payloadHash -ne $expectedHash) {
                throw "$operatingSystem 内置附件校验失败。期望 $expectedHash，实际 $payloadHash。"
            }
            Write-Host "SELFTEST_OK version=$ScriptVersion os=$operatingSystem payloadBytes=$($payloadBytes.Length) sha256=$payloadHash"
        }
        exit 0
    }
    catch {
        Write-Error "SELFTEST_FAILED: $($_.Exception.Message)"
        exit 1
    }
}

function Test-IsAdministrator {
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Restart-InWindowsPowerShellAsAdministrator {
    $isAdministrator = Test-IsAdministrator
    $isWindowsPowerShell = $PSVersionTable.PSEdition -eq 'Desktop'
    if ($isAdministrator -and $isWindowsPowerShell) {
        return
    }

    $argumentLine = "-NoLogo -NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    try {
        $startParameters = @{
            FilePath     = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
            ArgumentList = $argumentLine
        }
        if (-not $isAdministrator) {
            $startParameters.Verb = 'RunAs'
        }
        Start-Process @startParameters | Out-Null
    }
    catch {
        Write-Host "无法启动管理员版 Windows PowerShell：$($_.Exception.Message)" -ForegroundColor Red
        Read-Host '按 Enter 键退出'
    }
    exit
}

Restart-InWindowsPowerShellAsAdministrator

$timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$logPath = Join-Path $PSScriptRoot "manage-dedup-$timestamp.log"
$transcriptStarted = $false
try {
    Start-Transcript -LiteralPath $logPath -Force | Out-Null
    $transcriptStarted = $true
}
catch {
    $logPath = Join-Path $env:TEMP "manage-dedup-$timestamp.log"
    try {
        Start-Transcript -LiteralPath $logPath -Force | Out-Null
        $transcriptStarted = $true
    }
    catch {
        Write-Host '警告：无法启动操作日志。' -ForegroundColor Yellow
    }
}

function Pause-Menu {
    Read-Host '按 Enter 键继续' | Out-Null
}

function Confirm-Action {
    param([Parameter(Mandatory = $true)][string]$Message)

    $answer = Read-Host "$Message（输入 YES 确认）"
    return $answer -eq 'YES'
}

function Import-DedupModule {
    Import-Module Deduplication -ErrorAction Stop
}

function ConvertTo-NormalizedDriveName {
    param([Parameter(Mandatory = $true)]$Value)

    return ([string]$Value).Trim().TrimEnd('\').TrimEnd(':').ToUpperInvariant()
}

function Test-DedupJobIsActive {
    param([Parameter(Mandatory = $true)]$Job)

    return @('Queued', 'Running') -contains [string]$Job.State
}

function Get-DedupJobsForDrive {
    param([Parameter(Mandatory = $true)][string]$Drive)

    $normalizedDrive = ConvertTo-NormalizedDriveName $Drive
    return @(Get-DedupJob -ErrorAction Stop | Where-Object {
        (ConvertTo-NormalizedDriveName $_.Volume) -eq $normalizedDrive -and (Test-DedupJobIsActive $_)
    })
}

function Stop-DedupJobObjects {
    param([Parameter(Mandatory = $true)][object[]]$Jobs)

    try {
        for ($jobIndex = 0; $jobIndex -lt $Jobs.Count; $jobIndex++) {
            $job = $Jobs[$jobIndex]
            $taskType = ConvertTo-ChineseDedupType $job.Type
            $progressPercent = [int][Math]::Floor(($jobIndex * 100) / $Jobs.Count)
            Write-Progress -Id 20 -Activity '停止 Dedup 任务' -Status "正在处理第 $($jobIndex + 1)/$($Jobs.Count) 个：$taskType" -PercentComplete $progressPercent

            $freshJob = @(Get-DedupJob -ErrorAction Stop | Where-Object {
                [string]$_.Id -eq [string]$job.Id -and (Test-DedupJobIsActive $_)
            } | Select-Object -First 1)
            if ($freshJob.Count -eq 0) {
                Write-Host "任务已结束或已从队列移除，无需停止：$taskType，卷 $($job.Volume)。" -ForegroundColor Yellow
                continue
            }

            try {
                Stop-DedupJob -InputObject $freshJob[0] -ErrorAction Stop | Out-Null
                Write-Host "已提交停止：$(ConvertTo-ChineseDedupType $freshJob[0].Type)，卷 $($freshJob[0].Volume)。" -ForegroundColor Green
            }
            catch {
                if ($_.Exception.Message -match '0x80565301|找不到请求的对象|cannot find|not found') {
                    Write-Host "任务已在确认期间结束，无需停止：$taskType，卷 $($job.Volume)。" -ForegroundColor Yellow
                    continue
                }
                throw
            }
        }
    }
    finally {
        Write-Progress -Id 20 -Activity '停止 Dedup 任务' -Completed
    }
}

function Get-TargetDrive {
    $rawDrive = Read-Host '请输入数据盘盘符（例如 D）'
    $drive = $rawDrive.Trim().TrimEnd(':', '\').ToUpperInvariant()
    if ($drive -notmatch '^[A-Z]$') {
        throw '盘符格式无效，请输入一个英文字母。'
    }

    $systemDrive = $env:SystemDrive.TrimEnd(':', '\').ToUpperInvariant()
    if ($drive -eq $systemDrive) {
        throw "不允许对系统盘 ${drive}: 启用 Dedup。"
    }

    $volume = Get-Volume -DriveLetter $drive -ErrorAction Stop
    if ($volume.FileSystem -ne 'NTFS') {
        throw "${drive}: 的文件系统是 $($volume.FileSystem)，仅支持 NTFS 数据盘。"
    }
    if ($volume.DriveType -ne 'Fixed') {
        throw "${drive}: 不是固定数据盘。"
    }
    return $drive
}

function Get-DedupInstallationProfile {
    param([Parameter(Mandatory = $true)][int]$BuildNumber)

    if ($BuildNumber -ge 22000) {
        return [pscustomobject]@{
            OperatingSystem = 'Win11'
            DisplayName = 'Windows 11'
            ArchiveFileName = 'Dedup-Win11.7z'
            ArchiveSubdirectory = ''
            RequiredCabNames = @(
                'Microsoft-Windows-FileServer-ServerCore-Package-amd64-10.0.26100.1.cab',
                'Microsoft-Windows-FileServer-ServerCore-Package-amd64-10.0.26100.1-en-US.cab',
                'Microsoft-Windows-Dedup-Package-amd64-10.0.26100.1301.cab',
                'Microsoft-Windows-Dedup-Package-amd64-10.0.26100.1-en-US.cab'
            )
        }
    }

    # 目录映射在内部处理；界面统一显示 Windows 10。
    $packageDirectory = switch ($BuildNumber) {
        17763 { '10.0.17763'; break }
        { $_ -in @(18362, 18363) } { '10.0.18362'; break }
        { $_ -ge 19041 -and $_ -le 19043 } { '10.0.19041'; break }
        { $_ -in @(19044, 19045) } { '10.0.19044'; break }
        default { throw '当前 Windows 版本没有匹配的内置 Win10 组件，请提供对应组件包。' }
    }
    $baseVersion = switch ($packageDirectory) {
        '10.0.17763' { '10.0.17763.1' }
        '10.0.18362' { '10.0.18362.1' }
        default { '10.0.19041.1' }
    }
    $dedupVersion = if ($packageDirectory -eq '10.0.19044') { '10.0.19041.1202' } else { $baseVersion }
    return [pscustomobject]@{
        OperatingSystem = 'Win10'
        DisplayName = 'Windows 10'
        ArchiveFileName = 'Dedup-Win10.zip'
        ArchiveSubdirectory = $packageDirectory
        RequiredCabNames = @(
            "Microsoft-Windows-FileServer-ServerCore-Package~31bf3856ad364e35~amd64~~$baseVersion.cab",
            "Microsoft-Windows-FileServer-ServerCore-Package~31bf3856ad364e35~amd64~zh-CN~$baseVersion.cab",
            "Microsoft-Windows-Dedup-Package~31bf3856ad364e35~amd64~~$dedupVersion.cab",
            "Microsoft-Windows-Dedup-Package~31bf3856ad364e35~amd64~zh-CN~$baseVersion.cab"
        )
    }
}

function Test-SupportedOperatingSystem {
    $currentVersion = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    if ($currentVersion.InstallationType -ne 'Client' -or [int]$currentVersion.CurrentMajorVersionNumber -ne 10) {
        throw '此工具的内置安装包仅面向 Windows 10 / Windows 11 客户端。'
    }
    if ($env:PROCESSOR_ARCHITECTURE -ne 'AMD64') {
        throw "内置 CAB 仅支持 AMD64，请使用 64 位 Windows PowerShell。当前架构：$env:PROCESSOR_ARCHITECTURE。"
    }
    $installationProfile = Get-DedupInstallationProfile -BuildNumber ([int]$currentVersion.CurrentBuildNumber)
    Write-Host "系统版本：$($installationProfile.DisplayName) / $($currentVersion.EditionID) / AMD64"
    Write-Host '将使用内置的对应系统组件；安装适用性以 DISM 检查结果为准。' -ForegroundColor DarkGray
    return $installationProfile
}

function Remove-TemporaryDedupDirectory {
    param(
        [Parameter(Mandatory = $true)][string]$BasePath,
        [Parameter(Mandatory = $true)][string]$TargetPath
    )

    $baseFullPath = [IO.Path]::GetFullPath($BasePath).TrimEnd('\') + '\'
    $targetFullPath = [IO.Path]::GetFullPath($TargetPath).TrimEnd('\') + '\'
    if (-not $targetFullPath.StartsWith($baseFullPath, [StringComparison]::OrdinalIgnoreCase)) {
        throw "拒绝清理不在临时目录内的路径：$TargetPath"
    }
    if (Test-Path -LiteralPath $TargetPath) {
        Remove-Item -LiteralPath $TargetPath -Recurse -Force
    }
}

function Install-EmbeddedDedup {
    if (-not (Confirm-Action '将释放内置 CAB 并修改 Windows 组件，是否继续？')) {
        Write-Host '已取消安装。' -ForegroundColor Yellow
        return
    }

    $installationProfile = Test-SupportedOperatingSystem
    $tarPath = Join-Path $env:SystemRoot 'System32\tar.exe'
    $dismPath = Join-Path $env:SystemRoot 'System32\dism.exe'
    if ($installationProfile.OperatingSystem -eq 'Win11' -and -not (Test-Path -LiteralPath $tarPath)) { throw "找不到解压工具：$tarPath" }
    if (-not (Test-Path -LiteralPath $dismPath)) { throw "找不到 DISM：$dismPath" }

    $temporaryBase = Join-Path ([IO.Path]::GetTempPath()) 'DedupManager'
    $temporaryRoot = Join-Path $temporaryBase ([Guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $temporaryRoot -Force | Out-Null
    $archivePath = Join-Path $temporaryRoot $installationProfile.ArchiveFileName
    $extractPath = Join-Path $temporaryRoot 'extracted'
    New-Item -ItemType Directory -Path $extractPath -Force | Out-Null

    try {
        Write-Progress -Id 10 -Activity '安装 Dedup 组件' -Status '正在校验并释放内置附件' -PercentComplete 5
        Write-Host '正在校验并释放内置附件...' -ForegroundColor Cyan
        $payloadBytes = Get-EmbeddedArchiveBytes -OperatingSystem $installationProfile.OperatingSystem
        $payloadHash = Get-ByteArraySha256 -Bytes $payloadBytes
        $expectedHash = if ($installationProfile.OperatingSystem -eq 'Win10') { $EmbeddedWin10ArchiveSha256 } else { $EmbeddedArchiveSha256 }
        if ($payloadHash -ne $expectedHash) {
            throw "内置附件 SHA-256 校验失败。期望 $expectedHash，实际 $payloadHash。"
        }
        [IO.File]::WriteAllBytes($archivePath, $payloadBytes)

        Write-Progress -Id 10 -Activity '安装 Dedup 组件' -Status '正在解压内置附件' -PercentComplete 15
        if ($installationProfile.OperatingSystem -eq 'Win10') {
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            [IO.Compression.ZipFile]::ExtractToDirectory($archivePath, $extractPath)
        }
        else {
            & $tarPath -xf $archivePath -C $extractPath
            if ($LASTEXITCODE -ne 0) {
                throw "附件解压失败，tar.exe 退出码：$LASTEXITCODE。"
            }
        }

        $requiredCabNames = $installationProfile.RequiredCabNames
        $cabSearchPath = if ([string]::IsNullOrWhiteSpace($installationProfile.ArchiveSubdirectory)) {
            $extractPath
        } else {
            Join-Path $extractPath $installationProfile.ArchiveSubdirectory
        }

        $cabPaths = @()
        foreach ($cabName in $requiredCabNames) {
            $matches = @(Get-ChildItem -LiteralPath $cabSearchPath -Recurse -File -Filter $cabName)
            if ($matches.Count -ne 1 -or $matches[0].Length -le 0) {
                throw "附件内缺少或重复出现安装包：$cabName"
            }
            $cabPaths += $matches[0].FullName
        }

        $restartRequired = $false
        for ($cabIndex = 0; $cabIndex -lt $cabPaths.Count; $cabIndex++) {
            $cabPath = $cabPaths[$cabIndex]
            $installPercent = 25 + ($cabIndex * 15)
            Write-Progress -Id 10 -Activity '安装 Dedup 组件' -Status "正在安装第 $($cabIndex + 1)/$($cabPaths.Count) 个 CAB" -PercentComplete $installPercent
            Write-Host "正在安装：$(Split-Path -Leaf $cabPath)" -ForegroundColor Cyan
            $dismArguments = @('/Online', "/Add-Package:$cabPath", '/NoRestart')
            & $dismPath @dismArguments
            $exitCode = $LASTEXITCODE
            if ($exitCode -eq 3010) { $restartRequired = $true }
            elseif ($exitCode -ne 0) { throw "DISM 安装失败，退出码 $exitCode：$cabPath" }
        }

        Write-Progress -Id 10 -Activity '安装 Dedup 组件' -Status '正在启用 Dedup-Core' -PercentComplete 90
        Write-Host '正在启用 Dedup-Core...' -ForegroundColor Cyan
        & $dismPath /Online /Enable-Feature /FeatureName:Dedup-Core /All /NoRestart
        $exitCode = $LASTEXITCODE
        if ($exitCode -eq 3010) { $restartRequired = $true }
        elseif ($exitCode -ne 0) { throw "启用 Dedup-Core 失败，DISM 退出码：$exitCode。" }

        Write-Host 'Dedup 组件安装完成。' -ForegroundColor Green
        if ($restartRequired) {
            Write-Host 'Windows 要求重启。请重启后再启用数据盘去重。' -ForegroundColor Yellow
        }
        else {
            Write-Host '建议重启后再启用数据盘去重。' -ForegroundColor Yellow
        }
        Write-Progress -Id 10 -Activity '安装 Dedup 组件' -Status '安装完成' -PercentComplete 100
    }
    finally {
        Write-Progress -Id 10 -Activity '安装 Dedup 组件' -Completed
        try {
            Remove-TemporaryDedupDirectory -BasePath $temporaryBase -TargetPath $temporaryRoot
        }
        catch {
            Write-Host "临时文件清理失败：$($_.Exception.Message)" -ForegroundColor Yellow
        }
    }
}

function Enable-TargetDedup {
    Import-DedupModule
    $drive = Get-TargetDrive
    Write-Host '说明：文件达到指定天数后才参与去重；输入 0 表示不按文件年龄等待。' -ForegroundColor DarkGray
    $minimumFileAgeDays = 1
    while ($true) {
        $ageInput = Read-Host '请输入最小文件保留天数（非负整数，直接回车默认 1 天）'
        if ([string]::IsNullOrWhiteSpace($ageInput)) {
            $minimumFileAgeDays = 1
            break
        }
        $ageInput = $ageInput.Trim()
        if ($ageInput -match '^\d+$' -and [int]::TryParse($ageInput, [ref]$minimumFileAgeDays) -and $minimumFileAgeDays -ge 0) {
            break
        }
        Write-Host '输入无效，请输入 0 到 2147483647 之间的整数天数。' -ForegroundColor Yellow
    }
    if (-not (Confirm-Action "将在 ${drive}: 启用 Dedup，最小文件保留天数为 $minimumFileAgeDays 天，并排除 db/sqlite，是否继续？")) {
        Write-Host '已取消。' -ForegroundColor Yellow
        return
    }

    $currentJobs = @(Get-DedupJobsForDrive -Drive $drive)
    if (@($currentJobs | Where-Object { [string]$_.Type -eq 'Unoptimization' }).Count -gt 0) {
        throw "${drive}: 正在执行或等待取消优化，不能启动新的优化任务。"
    }

    Enable-DedupVolume -Volume "${drive}:" -ErrorAction Stop | Out-Null
    Set-DedupVolume -Volume "${drive}:" -ExcludeFileType @('db', 'sqlite') -MinimumFileAgeDays $minimumFileAgeDays -ErrorAction Stop | Out-Null
    if (@($currentJobs | Where-Object { [string]$_.Type -eq 'Optimization' }).Count -gt 0) {
        Write-Host "${drive}: 已存在运行中或排队中的优化任务，本次不再重复提交。" -ForegroundColor Yellow
    }
    else {
        Start-DedupJob -Type Optimization -Volume "${drive}:" -ErrorAction Stop | Out-Null
        Write-Host "已在 ${drive}: 启用 Dedup，并启动优化任务。" -ForegroundColor Green
    }
    Show-DedupLiveMonitor
}

function Start-TargetMaintenance {
    Import-DedupModule
    $drive = Get-TargetDrive
    if (-not (Confirm-Action "将在 ${drive}: 启动完整垃圾回收和完整性检查，是否继续？")) {
        Write-Host '已取消。' -ForegroundColor Yellow
        return
    }

    $currentJobs = @(Get-DedupJobsForDrive -Drive $drive)
    if (@($currentJobs | Where-Object { [string]$_.Type -eq 'Unoptimization' }).Count -gt 0) {
        throw "${drive}: 正在执行或等待取消优化，不能启动维护任务。"
    }

    $submittedCount = 0
    if (@($currentJobs | Where-Object { [string]$_.Type -eq 'GarbageCollection' }).Count -gt 0) {
        Write-Host '已存在运行中或排队中的垃圾回收任务，本次跳过。' -ForegroundColor Yellow
    }
    else {
        Start-DedupJob -Type GarbageCollection -Full -Volume "${drive}:" -ErrorAction Stop | Out-Null
        $submittedCount++
    }

    if (@($currentJobs | Where-Object { [string]$_.Type -eq 'Scrubbing' }).Count -gt 0) {
        Write-Host '已存在运行中或排队中的完整性检查任务，本次跳过。' -ForegroundColor Yellow
    }
    else {
        Start-DedupJob -Type Scrubbing -Volume "${drive}:" -ErrorAction Stop | Out-Null
        $submittedCount++
    }

    if ($submittedCount -gt 0) {
        Write-Host "已提交 $submittedCount 个维护任务。" -ForegroundColor Green
    }
    else {
        Write-Host '没有提交新的维护任务。' -ForegroundColor Yellow
    }
    Show-DedupLiveMonitor
}

function Set-WeekdaySchedule {
    Import-DedupModule
    if (-not (Confirm-Action '将创建或更新工作日 13:00、持续 5 小时的计划，是否继续？')) {
        Write-Host '已取消。' -ForegroundColor Yellow
        return
    }

    $days = @('Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday')
    $specifications = @(
        @{ Name = 'WeekdayOptimization'; Type = 'Optimization' },
        @{ Name = 'WeekdayGarbageCollection'; Type = 'GarbageCollection' }
    )
    foreach ($specification in $specifications) {
        $existing = Get-DedupSchedule -Name $specification.Name -ErrorAction SilentlyContinue
        if ($existing) {
            Set-DedupSchedule -Name $specification.Name -Days $days -Start '13:00' -DurationHours 5 -ErrorAction Stop | Out-Null
            Write-Host "已更新计划：$(ConvertTo-ChineseScheduleName $specification.Name)" -ForegroundColor Green
        }
        else {
            New-DedupSchedule -Name $specification.Name -Type $specification.Type -Days $days -Start '13:00' -DurationHours 5 -ErrorAction Stop | Out-Null
            Write-Host "已创建计划：$(ConvertTo-ChineseScheduleName $specification.Name)" -ForegroundColor Green
        }
    }
}

function ConvertTo-ChineseDedupType {
    param($Value)

    switch ([string]$Value) {
        'Optimization'      { return '优化' }
        'GarbageCollection' { return '垃圾回收' }
        'Scrubbing'         { return '完整性检查' }
        'Unoptimization'    { return '取消优化' }
        default             { if ([string]::IsNullOrWhiteSpace([string]$Value)) { return '-' }; return [string]$Value }
    }
}

function ConvertTo-ChineseJobState {
    param($Value)

    switch ([string]$Value) {
        'Queued'    { return '排队中' }
        'Running'   { return '运行中' }
        'Completed' { return '已完成' }
        'Failed'    { return '失败' }
        'Canceled'  { return '已取消' }
        'Cancelled' { return '已取消' }
        'Paused'    { return '已暂停' }
        'Suspended' { return '已暂停' }
        'Stopping'  { return '正在停止' }
        default     { if ([string]::IsNullOrWhiteSpace([string]$Value)) { return '-' }; return [string]$Value }
    }
}

function ConvertTo-ChineseScheduleType {
    param($Value)

    switch ([string]$Value) {
        'Manual'    { return '手动' }
        'Scheduled' { return '计划任务' }
        default     { if ([string]::IsNullOrWhiteSpace([string]$Value)) { return '-' }; return [string]$Value }
    }
}

function ConvertTo-ChineseScheduleName {
    param($Value)

    switch ([string]$Value) {
        'BackgroundOptimization'       { return '后台优化' }
        'WeeklyGarbageCollection'      { return '每周垃圾回收' }
        'WeeklyScrubbing'              { return '每周完整性检查' }
        'WeekdayOptimization'          { return '工作日优化' }
        'WeekdayGarbageCollection'     { return '工作日垃圾回收' }
        default                        { if ([string]::IsNullOrWhiteSpace([string]$Value)) { return '-' }; return [string]$Value }
    }
}

function ConvertTo-ChineseDays {
    param($Value)

    if ($null -eq $Value -or @($Value).Count -eq 0) { return '-' }
    $dayNames = @{
        Monday = '星期一'; Tuesday = '星期二'; Wednesday = '星期三'; Thursday = '星期四'
        Friday = '星期五'; Saturday = '星期六'; Sunday = '星期日'
    }
    $translatedDays = foreach ($item in @($Value)) {
        foreach ($day in ([string]$item -split '[,\s]+')) {
            if ([string]::IsNullOrWhiteSpace($day)) { continue }
            if ($dayNames.ContainsKey($day)) { $dayNames[$day] } else { $day }
        }
    }
    if (@($translatedDays).Count -eq 0) { return '-' }
    return (@($translatedDays) -join '、')
}

function ConvertTo-ChineseEnabledState {
    param($Value)

    if ($null -eq $Value) { return '-' }
    if ([bool]$Value) { return '已启用' }
    return '已禁用'
}

function Format-DedupDateTime {
    param($Value, [string]$Format = 'yyyy-MM-dd HH:mm:ss')

    if ($null -eq $Value -or [string]::IsNullOrWhiteSpace([string]$Value)) { return '-' }
    return ([datetime]$Value).ToString($Format)
}

function Show-DedupStatus {
    Import-DedupModule

    Write-Host '--- 去重状态 ---' -ForegroundColor Cyan
    $statuses = @(Get-DedupStatus -ErrorAction Stop)
    if ($statuses.Count -eq 0) {
        Write-Host '当前没有已启用 Dedup 的分区。' -ForegroundColor Yellow
    }
    else {
        $statusReport = foreach ($status in $statuses) {
            [pscustomobject][ordered]@{
                '卷'           = $status.Volume
                '可用空间'     = ConvertTo-FriendlySize $status.FreeSpace
                '已节省空间'   = ConvertTo-FriendlySize $status.SavedSpace
                '节省率'       = if ($null -eq $status.SavingsRate) { '-' } else { '{0:N1}%' -f [double]$status.SavingsRate }
                '已优化文件数' = $status.OptimizedFilesCount
                '策略内文件数' = $status.InPolicyFilesCount
            }
        }
        $statusReport | Format-Table -AutoSize | Out-Host
    }

    Write-Host '--- 当前任务 ---' -ForegroundColor Cyan
    $jobs = @(Get-DedupJob -ErrorAction Stop)
    if ($jobs.Count -eq 0) {
        Write-Host '当前没有正在运行或排队的 Dedup 任务。' -ForegroundColor Yellow
    }
    else {
        $jobReport = foreach ($job in $jobs) {
            [pscustomobject][ordered]@{
                '任务类型' = ConvertTo-ChineseDedupType $job.Type
                '执行方式' = ConvertTo-ChineseScheduleType $job.ScheduleType
                '开始时间' = Format-DedupDateTime $job.StartTime 'HH:mm:ss'
                '完成进度' = if ($null -eq $job.Progress) { '-' } else { '{0:N0}%' -f [double]$job.Progress }
                '状态'     = ConvertTo-ChineseJobState $job.State
                '卷'       = $job.Volume
            }
        }
        $jobReport | Format-Table -AutoSize | Out-Host
    }

    Write-Host '--- 定时计划 ---' -ForegroundColor Cyan
    $schedules = @(Get-DedupSchedule -ErrorAction Stop)
    if ($schedules.Count -eq 0) {
        Write-Host '当前没有 Dedup 定时计划。' -ForegroundColor Yellow
    }
    else {
        $scheduleReport = foreach ($schedule in $schedules) {
            [pscustomobject][ordered]@{
                '启用状态' = ConvertTo-ChineseEnabledState $schedule.Enabled
                '任务类型' = ConvertTo-ChineseDedupType $schedule.Type
                '开始时间' = Format-DedupDateTime $schedule.Start 'HH:mm'
                '执行日期' = ConvertTo-ChineseDays $schedule.Days
                '计划名称' = ConvertTo-ChineseScheduleName $schedule.Name
            }
        }
        $scheduleReport | Format-Table -AutoSize | Out-Host
    }
}

function ConvertTo-FriendlySize {
    param($Bytes)

    if ($null -eq $Bytes) { return '-' }
    $size = [double]$Bytes
    $units = @('B', 'KB', 'MB', 'GB', 'TB', 'PB')
    $unitIndex = 0
    while ($size -ge 1024 -and $unitIndex -lt ($units.Count - 1)) {
        $size /= 1024
        $unitIndex++
    }
    return ('{0:N2} {1}' -f $size, $units[$unitIndex])
}

function Show-DedupOptimizationReport {
    Import-DedupModule
    $statuses = @(Get-DedupStatus -ErrorAction Stop)
    if ($statuses.Count -eq 0) {
        Write-Host '当前没有已启用 Dedup 的分区。' -ForegroundColor Yellow
        return
    }

    Write-Host '--- 磁盘空间优化率 ---' -ForegroundColor Cyan
    $report = foreach ($status in $statuses) {
        $savingsRate = if ($null -eq $status.SavingsRate) {
            '-'
        }
        else {
            '{0:N1}%' -f [double]$status.SavingsRate
        }
        $lastOptimization = if ($null -eq $status.LastOptimizationTime) {
            '-'
        }
        else {
            ([datetime]$status.LastOptimizationTime).ToString('yyyy-MM-dd HH:mm:ss')
        }

        [pscustomobject][ordered]@{
            '卷'           = $status.Volume
            '节省率'       = $savingsRate
            '已节省空间'   = ConvertTo-FriendlySize $status.SavedSpace
            '已优化文件数' = if ($null -eq $status.OptimizedFilesCount) { '-' } else { $status.OptimizedFilesCount }
            '策略内文件数' = if ($null -eq $status.InPolicyFilesCount) { '-' } else { $status.InPolicyFilesCount }
            '最近优化时间' = $lastOptimization
        }
    }
    $report | Format-Table -AutoSize | Out-Host

    Write-Host '说明：节省率表示 Dedup 已减少的实际磁盘占用，不代表当前任务完成进度。' -ForegroundColor DarkGray
    Write-Host '--- 当前 Dedup 任务进度 ---' -ForegroundColor Cyan
    $jobs = @(Get-DedupJob -ErrorAction Stop)
    if ($jobs.Count -eq 0) {
        Write-Host '当前没有正在运行的 Dedup 任务。' -ForegroundColor Yellow
        return
    }

    $jobReport = foreach ($job in $jobs) {
        [pscustomobject][ordered]@{
            '卷'       = $job.Volume
            '任务类型' = ConvertTo-ChineseDedupType $job.Type
            '执行方式' = ConvertTo-ChineseScheduleType $job.ScheduleType
            '状态'     = ConvertTo-ChineseJobState $job.State
            '完成进度' = if ($null -eq $job.Progress) { '-' } else { '{0:N1}%' -f [double]$job.Progress }
            '开始时间' = if ($null -eq $job.StartTime) { '-' } else { ([datetime]$job.StartTime).ToString('yyyy-MM-dd HH:mm:ss') }
        }
    }
    $jobReport | Format-Table -AutoSize | Out-Host
}

function Format-TextProgressBar {
    param(
        $Percent,
        [ValidateRange(10, 60)][int]$Width = 30
    )

    $numericPercent = if ($null -eq $Percent) { 0 } else { [double]$Percent }
    $numericPercent = [Math]::Max(0, [Math]::Min(100, $numericPercent))
    $completedWidth = [int][Math]::Floor($numericPercent * $Width / 100)
    return ('[{0}{1}] {2:N0}%' -f ('#' * $completedWidth), ('-' * ($Width - $completedWidth)), $numericPercent)
}

function Clear-DedupMonitorScreen {
    try {
        Clear-Host -ErrorAction Stop
    }
    catch {
        Write-Host ''
        Write-Host '----------------------------------------' -ForegroundColor DarkGray
    }
}

function Show-DedupLiveMonitor {
    param(
        [ValidateRange(0, 1000000)][int]$MaximumIterations = 0,
        [ValidateRange(1, 60000)][int]$RefreshMilliseconds = 2000
    )

    Import-DedupModule
    $iteration = 0
    $consoleInputAvailable = $false
    $consoleControlConfigured = $false
    $originalTreatControlCAsInput = $false
    try {
        $originalTreatControlCAsInput = [Console]::TreatControlCAsInput
        [Console]::TreatControlCAsInput = $true
        $consoleInputAvailable = $true
        $consoleControlConfigured = $true
    }
    catch {
        $consoleInputAvailable = $false
    }

    try {
        while ($true) {
            $iteration++
            $statuses = @(Get-DedupStatus -ErrorAction Stop)
            $jobs = @(Get-DedupJob -ErrorAction Stop | Where-Object { Test-DedupJobIsActive $_ })

            Clear-DedupMonitorScreen
            Write-Host '===== Dedup 实时监控 =====' -ForegroundColor Cyan
            Write-Host "更新时间：$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
            Write-Host '每 2 秒自动刷新；按 Q 或 Ctrl+C 返回主菜单。' -ForegroundColor DarkGray
            Write-Host ''
            Write-Host '--- 磁盘空间节省情况 ---' -ForegroundColor Cyan

            if ($statuses.Count -eq 0) {
                Write-Host '当前没有已启用 Dedup 的分区。' -ForegroundColor Yellow
            }
            else {
                $statusReport = foreach ($status in $statuses) {
                    [pscustomobject][ordered]@{
                        '卷'           = $status.Volume
                        '节省率'       = if ($null -eq $status.SavingsRate) { '-' } else { '{0:N1}%' -f [double]$status.SavingsRate }
                        '已节省空间'   = ConvertTo-FriendlySize $status.SavedSpace
                        '已优化文件数' = $status.OptimizedFilesCount
                        '策略内文件数' = $status.InPolicyFilesCount
                        '最近优化时间' = Format-DedupDateTime $status.LastOptimizationTime
                    }
                }
                $statusReport | Format-Table -AutoSize | Out-Host
            }

            Write-Host '--- 当前任务动态进度 ---' -ForegroundColor Cyan
            if ($jobs.Count -eq 0) {
                Write-Host '当前没有运行中或排队中的 Dedup 任务。' -ForegroundColor Yellow
            }
            else {
                foreach ($job in $jobs) {
                    $taskType = ConvertTo-ChineseDedupType $job.Type
                    $taskState = ConvertTo-ChineseJobState $job.State
                    Write-Host "$($job.Volume)  $taskType  $taskState"
                    Write-Host (Format-TextProgressBar -Percent $job.Progress) -ForegroundColor Green
                }
            }

            if ($MaximumIterations -gt 0 -and $iteration -ge $MaximumIterations) {
                return
            }

            $waitedMilliseconds = 0
            while ($waitedMilliseconds -lt $RefreshMilliseconds) {
                if ($consoleInputAvailable) {
                    try {
                        while ([Console]::KeyAvailable) {
                            $keyInfo = [Console]::ReadKey($true)
                            $isControlC = $keyInfo.Key -eq [ConsoleKey]::C -and (($keyInfo.Modifiers -band [ConsoleModifiers]::Control) -ne 0)
                            if ($keyInfo.Key -eq [ConsoleKey]::Q -or $isControlC) {
                                return
                            }
                        }
                    }
                    catch {
                        $consoleInputAvailable = $false
                    }
                }
                $sleepDuration = [Math]::Min(100, $RefreshMilliseconds - $waitedMilliseconds)
                Start-Sleep -Milliseconds $sleepDuration
                $waitedMilliseconds += $sleepDuration
            }
        }
    }
    finally {
        if ($consoleControlConfigured) {
            try { [Console]::TreatControlCAsInput = $originalTreatControlCAsInput } catch { }
        }
        $script:SkipNextMenuPause = $true
        Clear-DedupMonitorScreen
    }
}

function ConvertFrom-DedupJobSelection {
    param(
        [Parameter(Mandatory = $true)][string]$InputText,
        [Parameter(Mandatory = $true)][ValidateRange(1, 2147483647)][int]$MaximumNumber
    )

    $normalizedInput = $InputText.Trim().Replace('，', ',')
    if ($normalizedInput -eq 'A') {
        return @(1..$MaximumNumber)
    }
    if ([string]::IsNullOrWhiteSpace($normalizedInput)) {
        throw '未输入任务编号。'
    }

    $selectedNumbers = @()
    $parts = @($normalizedInput -split '[,\s]+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    foreach ($part in $parts) {
        if ($part -match '^\d+$') {
            $selectedNumbers += [int]$part
            continue
        }
        if ($part -match '^(\d+)-(\d+)$') {
            $rangeStart = [int]$Matches[1]
            $rangeEnd = [int]$Matches[2]
            if ($rangeStart -gt $rangeEnd) {
                throw "任务编号范围无效：$part。起始编号不能大于结束编号。"
            }
            $selectedNumbers += @($rangeStart..$rangeEnd)
            continue
        }
        throw "无法识别的任务编号格式：$part。"
    }

    $selectedNumbers = @($selectedNumbers | Sort-Object -Unique)
    foreach ($number in $selectedNumbers) {
        if ($number -lt 1 -or $number -gt $MaximumNumber) {
            throw "任务编号 $number 超出有效范围 1-$MaximumNumber。"
        }
    }
    return $selectedNumbers
}

function Stop-SelectedDedupJobs {
    Import-DedupModule
    $drive = Get-TargetDrive
    $jobs = @(Get-DedupJobsForDrive -Drive $drive)
    if ($jobs.Count -eq 0) {
        Write-Host "${drive}: 当前没有运行中或排队中的 Dedup 任务。" -ForegroundColor Yellow
        return
    }

    Write-Host "--- ${drive}: 可停止的任务 ---" -ForegroundColor Cyan
    $jobReport = for ($index = 0; $index -lt $jobs.Count; $index++) {
        $job = $jobs[$index]
        [pscustomobject][ordered]@{
            '编号'     = $index + 1
            '任务类型' = ConvertTo-ChineseDedupType $job.Type
            '状态'     = ConvertTo-ChineseJobState $job.State
            '完成进度' = if ($null -eq $job.Progress) { '-' } else { '{0:N0}%' -f [double]$job.Progress }
            '卷'       = $job.Volume
        }
    }
    $jobReport | Format-Table -AutoSize | Out-Host

    $selection = Read-Host '输入编号（如 1,3、1-3 或 1,3-5）；输入 A 选择全部任务'
    $selectedNumbers = @(ConvertFrom-DedupJobSelection -InputText $selection -MaximumNumber $jobs.Count)
    $selectedJobs = @($selectedNumbers | ForEach-Object { $jobs[$_ - 1] })
    $description = "${drive}: 上编号为 $($selectedNumbers -join '、') 的 $($selectedJobs.Count) 个任务"

    Write-Host '--- 最终选择的任务 ---' -ForegroundColor Cyan
    $selectedReport = for ($index = 0; $index -lt $selectedJobs.Count; $index++) {
        $job = $selectedJobs[$index]
        [pscustomobject][ordered]@{
            '编号'     = $selectedNumbers[$index]
            '任务类型' = ConvertTo-ChineseDedupType $job.Type
            '状态'     = ConvertTo-ChineseJobState $job.State
            '完成进度' = if ($null -eq $job.Progress) { '-' } else { '{0:N0}%' -f [double]$job.Progress }
            '卷'       = $job.Volume
        }
    }
    $selectedReport | Format-Table -AutoSize | Out-Host

    if (-not (Confirm-Action "将停止$description，是否继续？")) {
        Write-Host '已取消停止任务。' -ForegroundColor Yellow
        return
    }
    Stop-DedupJobObjects -Jobs $selectedJobs
}

function Start-TargetUnoptimization {
    Import-DedupModule
    $drive = Get-TargetDrive
    Write-Host '取消优化会把去重数据重新展开，需要足够可用空间；完成前不要重装系统或拆卸磁盘。' -ForegroundColor Yellow

    $currentJobs = @(Get-DedupJobsForDrive -Drive $drive)
    $existingUnoptimization = @($currentJobs | Where-Object { [string]$_.Type -eq 'Unoptimization' })
    $conflictingJobs = @($currentJobs | Where-Object {
        [string]$_.Type -in @('Optimization', 'GarbageCollection', 'Scrubbing')
    })
    if ($conflictingJobs.Count -gt 0) {
        Write-Host "${drive}: 存在 $($conflictingJobs.Count) 个冲突任务：" -ForegroundColor Yellow
        $conflictingJobs | ForEach-Object {
            [pscustomobject][ordered]@{
                '任务类型' = ConvertTo-ChineseDedupType $_.Type
                '状态'     = ConvertTo-ChineseJobState $_.State
                '完成进度' = if ($null -eq $_.Progress) { '-' } else { '{0:N0}%' -f [double]$_.Progress }
            }
        } | Format-Table -AutoSize | Out-Host

        if (-not (Confirm-Action '必须先停止这些冲突任务，是否停止并继续取消优化？')) {
            Write-Host '已取消启动取消优化。' -ForegroundColor Yellow
            return
        }
        Stop-DedupJobObjects -Jobs $conflictingJobs
    }

    if ($existingUnoptimization.Count -gt 0) {
        Write-Host "${drive}: 已存在取消优化任务；冲突任务处理完成后会继续执行，无需重复提交。" -ForegroundColor Green
        Show-DedupLiveMonitor
        return
    }

    if (-not (Confirm-Action "将在 ${drive}: 启动取消优化（Unoptimization），是否继续？")) {
        Write-Host '已取消。' -ForegroundColor Yellow
        return
    }

    Start-DedupJob -Type Unoptimization -Volume "${drive}:\" -ErrorAction Stop | Out-Null
    Write-Host '取消优化任务已启动。请通过“查看状态”等待任务完成。' -ForegroundColor Green
    Show-DedupLiveMonitor
}

try {
    $running = $true
    while ($running) {
        Clear-Host
        Write-Host "===== Dedup 管理工具 v$ScriptVersion =====" -ForegroundColor Cyan
        Write-Host '1. 一键释放并安装内置 Dedup 组件'
        Write-Host '2. 在数据盘启用 Dedup 并启动优化'
        Write-Host '3. 启动垃圾回收与完整性检查'
        Write-Host '4. 创建/更新工作日定时计划'
        Write-Host '5. 查看 Dedup 状态、任务和计划'
        Write-Host '6. 实时查看磁盘优化率和任务进度'
        Write-Host '7. 停止运行中或排队中的 Dedup 任务'
        Write-Host '8. 启动取消优化（换机/重装前）'
        Write-Host '9. 退出'
        Write-Host "日志：$logPath" -ForegroundColor DarkGray
        $choice = Read-Host '请选择'

        $script:SkipNextMenuPause = $false
        try {
            switch ($choice) {
                '1' { Install-EmbeddedDedup }
                '2' { Enable-TargetDedup }
                '3' { Start-TargetMaintenance }
                '4' { Set-WeekdaySchedule }
                '5' { Show-DedupStatus }
                '6' { Show-DedupLiveMonitor }
                '7' { Stop-SelectedDedupJobs }
                '8' { Start-TargetUnoptimization }
                '9' { $running = $false }
                default { Write-Host '无效选项，请输入 1-9。' -ForegroundColor Yellow }
            }
        }
        catch {
            Write-Host "操作失败：$($_.Exception.Message)" -ForegroundColor Red
            Write-Host "详细信息已记录到：$logPath" -ForegroundColor Yellow
            $_ | Format-List * -Force | Out-Host
        }

        if ($running -and -not $script:SkipNextMenuPause) {
            Pause-Menu
        }
    }

    Write-Host "已退出。日志保存在：$logPath" -ForegroundColor Green
    Read-Host '按 Enter 键关闭窗口' | Out-Null
}
catch {
    Write-Host "程序发生未处理错误：$($_.Exception.Message)" -ForegroundColor Red
    $_ | Format-List * -Force | Out-Host
    Read-Host '按 Enter 键退出' | Out-Null
}
finally {
    if ($transcriptStarted) {
        try { Stop-Transcript | Out-Null } catch { }
    }
}
